targets.expr:
sort_desc(
  (1 - libvirt_domain_memory_stats_usable_bytes{domain=~"$domain",job=~"libvirt_exporter",compute=~"$compute"}
    / libvirt_domain_info_maximum_memory_bytes{domain=~"$domain",job=~"libvirt_exporter",compute=~"$compute"}) * 100
  * on(domain) group_left(instance_name) max by (domain, instance_name) (libvirt_domain_openstack_info{domain=~"$domain",job=~"libvirt_exporter",compute=~"$compute"})
)
